class Solution {
public:
    int singleNumber(vector<int>& nums) {
        int res = 0;
        for (int bit = 0; bit < 32; bit++) {
            int cnt = 0;
            for (int x : nums) cnt += (x >> bit) & 1;
            if (cnt % 3) res |= (1u << bit);
        }
        return res;
    }
};
